.fields .kind-options label{display:block;position:relative;cursor:pointer}
.fields .kind-options input{position:absolute;opacity:0;width:1px;height:1px;margin:0;padding:0;border:0}
.kind-options span{display:flex;align-items:center;height:38px;padding:0 16px;font:11px/1.5 Galmuri,monospace;color:#a7bfba;background:#13232b}
.kind-options span::before{content:"○";margin-right:6px}
.kind-options label+label span{border-left:1px dashed #78918d65}
.kind-options label:hover span{color:#e8f2ed}
.kind-options input:checked+span{background:#30483f;color:#e1eee7;font-weight:700}
.kind-options input:checked+span::before{content:"●"}
.kind-options input:focus-visible+span{outline:2px solid #9fc5b0;outline-offset:-2px}
/* Sidebar starts level with the list header. */
.layout aside{margin-top:var(--aside-offset,0)}
@media(max-width:600px){.layout aside{margin-top:0}}
/* Topic hover: a branch tick grows from the dotted rail, the row lifts slightly. */
.topic{position:relative;padding:3px 6px;margin:-3px -6px;border-radius:4px;transition:color .18s,background-color .18s,transform .18s}
.topic::before{content:"";position:absolute;left:-14px;top:50%;width:0;height:1px;background:#b9d7c6;transition:width .18s}
.topic:hover{color:#eef7f2;background:#2b434866;transform:translateX(3px)}
.topic:hover::before{width:11px}
.topic:hover .count{color:#cfe3da}
.topic:hover input{border-color:#b9d7c6;box-shadow:0 0 0 2px #b9d7c626}
.topic:has(input:focus-visible){background:#2b434866}
@media(max-width:600px){.topic::before{display:none}}
@media(prefers-reduced-motion:reduce){.topic,.topic::before{transition:none}.topic:hover{transform:none}}
/* Topic colours: dimmer at rest, white on hover; selected stays bright. */
.topic{color:#7f9497}.topic .count{color:#5f7477}
.topic input{border-color:#62777a}
.topic:hover,.topic:has(input:focus-visible){color:#eef7f2}
.topic:has(input:checked){color:#e4f2e8}
/* Inline topic editing keeps the normal row: only the name becomes editable text. */
.layout aside.editing .topics{grid-template-columns:minmax(0,1fr)}
.topic.topic-edit{cursor:text;min-width:0}
.topic.topic-edit::before{display:none}.topic.topic-edit:hover,.topic.topic-edit:focus-within{transform:none;color:#eef7f2;background:#2b434866}
.topic .box{flex:none;display:inline-grid;place-items:center;width:12px;height:12px;border:1px solid #62777a;background:#16242b;font-size:10px;line-height:1}
.topic-edit:hover .box,.topic-edit:focus-within .box{border-color:#b9d7c6}
.topic input.topic-name{appearance:none;flex:1 1 auto;width:0;height:auto;min-width:0;margin:0 0 -1px;padding:0;font:inherit;line-height:inherit;color:inherit;letter-spacing:inherit;background:transparent;border:0;border-bottom:1px dashed #78918d44;border-radius:0;box-shadow:none}
.topic input.topic-name:focus{outline:none;border-bottom:1px solid #b9d7c6;box-shadow:none}
.topic-name::placeholder{color:#5f7477}
.topic-remove{flex:none;padding:0 2px;margin-left:-4px;font:12px/1 monospace;color:#6f8487;background:none;border:0;opacity:0;transition:opacity .15s,color .15s}
.topic-edit:hover .topic-remove,.topic-edit:focus-within .topic-remove,.topic-remove:focus-visible{opacity:1}
.topic-remove:hover{color:#f0a3a3}
@media(hover:none){.topic-remove{opacity:1}}
.topic.topic-add{width:100%;text-align:left;font-family:inherit;line-height:inherit;background:none;border:0;color:#5f7477}
.topic.topic-add .box{border-style:dashed;color:inherit;background:none}
.topic.topic-add:hover{color:#eef7f2}
.topic-actions{display:flex;justify-content:flex-end;gap:6px;margin-top:6px}
.topic-actions .small{font-size:10px;padding:6px 10px;border:1px dashed #819e9577;background:#263a3e;color:#b9cec6}
.topic-actions .small.active{background:#b9d5c5;color:#1b3028;border-color:#d0e6d8;font-weight:700}
@media(max-width:600px){.layout aside.editing .topics{display:grid}}
/* List rows: dimmer at rest, white on hover or when open. */
.entry .title{color:#91a4a6;transition:color .18s}.entry .date{color:#6b8084;transition:color .18s}.entry .plus{color:#647a7e;transition:color .18s}
.entry summary:hover .title,.entry summary:focus-visible .title,.entry[open] .title{color:#e8efee}
.entry summary:hover .date,.entry summary:focus-visible .date,.entry[open] .date{color:#bcd0d3}
.entry summary:hover .plus,.entry[open] .plus{color:#dbe8e7}
/* Editor: borderless and quiet; only a grip remains for dragging. */
#editor{border:0;width:min(760px,calc(100% - 32px));padding:18px 38px 26px}
#editor .note-heading{border:0;margin:0 0 14px;padding:6px 0 10px;justify-content:center;background:#192730;top:-18px}
#editor .grip{display:block;width:44px;height:4px;border-radius:2px;background:#7b999355}
#editor .note-heading:hover .grip{background:#9fc5b0aa}
#editor .fields .note-title input{border-bottom:0;padding-bottom:8px}
#editor .form-actions{border-top:0;margin-top:18px;padding-top:0}
.note-photos{grid-column:1/-1;grid-row:4;display:grid;gap:10px}
.photo-list{display:flex;flex-wrap:wrap;gap:10px}.photo-list:empty{display:none}
.photo-thumb{position:relative;margin:0;width:112px;height:112px;border-radius:6px;overflow:hidden;background:#101f28}
.photo-thumb img{width:100%;height:100%;object-fit:cover;display:block}
.photo-thumb button{position:absolute;top:5px;right:5px;width:22px;height:22px;border-radius:50%;background:#0b141bcc;color:#e8f2ed;font:13px/1 monospace;padding:0;opacity:0;transition:opacity .15s}
.photo-thumb:hover button,.photo-thumb button:focus-visible{opacity:1}
@media(hover:none){.photo-thumb button{opacity:1}}
.photo-add{justify-self:start;padding:8px 12px;font:11px Galmuri,monospace;color:#bed3ca;background:transparent;border:1px dashed #819e9577;border-radius:5px}
.photo-add span{color:#7f9792;margin-left:6px}
.photo-add:hover{background:#263a3e;color:#e8f2ed}
.drop-hint{display:none}
#editor.dropping .drop-hint{display:grid;place-items:center;position:absolute;inset:10px;border:1px dashed #b9d7c6;border-radius:10px;background:#13232bdd;color:#e1eee7;font:13px Galmuri,monospace;pointer-events:none;z-index:2}
.photos{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 20px}
.photos a{display:block;border-radius:6px;overflow:hidden;line-height:0}
.photos img{height:150px;max-width:100%;object-fit:cover;display:block;transition:opacity .15s}
.photos a:hover img{opacity:.85}
@media(max-width:600px){#editor{padding:14px 20px 22px}.photo-thumb{width:88px;height:88px}.photos img{height:110px}}
/* Markdown reading view. */
.prose{font-size:15px;line-height:1.85;color:#ccd9da;max-width:780px;overflow-wrap:anywhere;margin:0 0 20px}
.prose>:first-child{margin-top:0}.prose>:last-child{margin-bottom:0}
.detail .prose p,.prose p{white-space:normal;font-size:inherit;line-height:inherit;color:inherit;max-width:none;margin:0 0 1.1em}
.prose h1,.prose h2,.prose h3,.prose h4{color:#e8efee;font-weight:700;line-height:1.4;margin:1.7em 0 .6em}
.prose h1{font-size:23px}.prose h2{font-size:19px}.prose h3{font-size:16px}.prose h4{font-size:15px;color:#cfe0dc}
.prose a{color:#d8ece3;text-decoration:underline;text-underline-offset:3px;text-decoration-color:#9fc5b088}.prose a:hover{text-decoration-color:#d8ece3}
.prose strong{color:#e8efee}
.prose ul,.prose ol{padding-left:1.4em;margin:0 0 1.1em}.prose li{margin:.2em 0}.prose li::marker{color:#7f9792}
.prose blockquote{margin:0 0 1.1em;padding:2px 0 2px 14px;border-left:2px solid #9fc5b066;color:#a9bdbd}
.prose hr{border:0;border-top:1px dashed #78918d55;margin:2em 0}
.prose :not(pre)>code{font:.87em/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;background:#0f1c23;border:1px solid #78918d33;border-radius:4px;padding:1px 5px;color:#dfece6}
.prose img{display:block;max-width:100%;height:auto;border-radius:6px;margin:6px 0 1.1em;cursor:zoom-in;background:#101f28}
.prose .photos{display:flex;flex-wrap:wrap;gap:10px}.prose .photos img{height:150px;width:auto;margin:0;object-fit:cover}
.photo-missing{display:block;color:#7f9792;font:11px Galmuri,monospace;margin:0 0 1em}
.prose table{display:block;overflow-x:auto;border-collapse:collapse;margin:0 0 1.1em;font-size:13px}
.prose th,.prose td{border:1px solid #78918d44;padding:6px 10px;text-align:left}.prose th{background:#13232b;color:#e1eee7}
.code-block{margin:0 0 1.25em;border:1px solid #78918d33;border-radius:8px;overflow:hidden;background:#0c171e}
.code-bar{display:flex;justify-content:space-between;align-items:center;padding:5px 8px 5px 14px;font:10px Galmuri,monospace;color:#7f9792;border-bottom:1px solid #78918d22}
.code-copy{background:none;color:#a7bfba;font:10px Galmuri,monospace;padding:3px 7px;border-radius:3px}.code-copy:hover{background:#263a3e;color:#e8f2ed}
.code-block pre{margin:0;padding:14px 16px;overflow-x:auto}
.code-block code{font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:#d2e0db;white-space:pre}
.hljs-comment,.hljs-quote{color:#6f8a87;font-style:italic}
.hljs-keyword,.hljs-selector-tag,.hljs-doctag,.hljs-section{color:#c9a8ec}
.hljs-string,.hljs-regexp,.hljs-addition,.hljs-template-tag{color:#b5dfa0}
.hljs-number,.hljs-literal,.hljs-symbol,.hljs-bullet{color:#f2c48d}
.hljs-title,.hljs-title.function_,.hljs-name{color:#86d4c6}
.hljs-attr,.hljs-attribute,.hljs-property,.hljs-selector-attr,.hljs-selector-class,.hljs-selector-id{color:#e8b27c}
.hljs-built_in,.hljs-type,.hljs-title.class_{color:#f0d68c}
.hljs-variable,.hljs-params,.hljs-template-variable{color:#d2e0db}
.hljs-meta{color:#7fb6c9}.hljs-deletion{color:#f0a3a3}.hljs-emphasis{font-style:italic}.hljs-strong{font-weight:700}
/* Editor: write / preview tabs. */
#editor [hidden]{display:none!important}
.write-tabs{grid-column:1/-1;grid-row:3;display:flex;align-items:center;gap:4px;margin-bottom:-6px}
.write-tabs button{font:11px Galmuri,monospace;color:#7f9792;background:none;padding:5px 9px;border-radius:4px}
.write-tabs button:hover{color:#e8f2ed}
.write-tabs button[aria-selected=true]{color:#e1eee7;background:#263a3e}
.md-hint{margin-left:auto;font:10px Galmuri,monospace;color:#5f7477}
#editor .fields .note-body{grid-row:4}
.md-preview{grid-column:1/-1;grid-row:4;font-size:14px;margin:0;padding:4px 4px 0;max-width:none;overflow:auto;max-height:60vh}
#editor .fields .note-body textarea{font:13px/32px Galmuri,monospace;min-height:260px}
#editor .note-photos{grid-row:5}
@media(max-width:600px){.md-hint{display:none}.prose{font-size:14px}}
